protected override void OnModelCreating(ModelBuilder b)
{
    // One Blog — many Posts (required author): cascade by default
    b.Entity<Post>()
        .HasOne(p => p.Blog)
        .WithMany(bl => bl.Posts)
        .HasForeignKey(p => p.BlogId)
        .OnDelete(DeleteBehavior.Cascade);

    // Optional parent: deleting the Author nulls the FK
    b.Entity<Post>()
        .HasOne(p => p.Author)
        .WithMany(a => a.Posts)
        .HasForeignKey(p => p.AuthorId)
        .OnDelete(DeleteBehavior.SetNull);

    // One-to-one with dependent PK = FK
    b.Entity<AuthorProfile>()
        .HasOne(p => p.Author)
        .WithOne(a => a.Profile)
        .HasForeignKey<AuthorProfile>(p => p.AuthorId);

    // Many-to-many with payload: explicit join entity
    b.Entity<PostTag>(e =>
    {
        e.HasKey(t => new { t.PostId, t.TagId });          // composite key
        e.HasOne(t => t.Post).WithMany(p => p.PostTags)
            .HasForeignKey(t => t.PostId)
            .OnDelete(DeleteBehavior.Cascade);
        e.HasOne(t => t.Tag).WithMany(t => t.PostTags)
            .HasForeignKey(t => t.TagId)
            .OnDelete(DeleteBehavior.Restrict);           // don't delete tags with posts
    });
}

